"use client";
/**
 * EosMarketCard: a hairline card with an inset gradient banner of app tiles, a title, a subline and a quiet meta row
 * (installs, "by", a small maker mark and the maker). The "frame" media puts a big serif title over a wide pale
 * specimen frame with a thin gradient band instead. Inside an Eos scope the card follows the look: the editorial
 * look gives it the frame, and the night look frosted tiles.
 *
 * On hover the card lifts a few px while a deeper shadow and a stronger hairline fade in on layers of their own, and
 * its tiles lift one after another; a press settles it to 0.98. Pass the eos-rise class and a delay (motion.ts) to
 * have it rise in with a page.
 */
import type { CSSProperties, HTMLAttributes, MouseEventHandler } from "react";
import { EosGradientBanner } from "./gradient-banner";
import { EosMark, type EosAppKind, type EosMarkKind } from "./glyphs";
import { EosIconTile, type EosIconTileSize, type EosIconTileTone } from "./icon-tile";
import { cx, SR_ONLY_CSS } from "./shared";
import { EosScope, useEosTheme } from "./theme";
import { EOS_LOOK_SPECS, type EosGradientName } from "./tokens";

const CSS = `
.eos-mcard{position:relative;display:flex;flex-direction:column;min-width:0;box-sizing:border-box;padding:var(--eos-banner-inset);border-radius:var(--eos-radius-card);background:var(--eos-card);border:1px solid var(--eos-hairline);box-shadow:var(--eos-card-shadow);-webkit-backdrop-filter:blur(var(--eos-card-blur));backdrop-filter:blur(var(--eos-card-blur));color:var(--eos-text);font-family:var(--eos-font-body);transition:transform var(--eos-dur-hover) var(--eos-ease)}
.eos-mcard::before,.eos-mcard::after{content:"";position:absolute;inset:-1px;border-radius:inherit;opacity:0;pointer-events:none;transition:opacity var(--eos-dur-hover) var(--eos-ease)}
.eos-mcard::before{box-shadow:var(--eos-lift-shadow)}
.eos-mcard::after{z-index:4;border:1px solid var(--eos-hairline-strong)}
@media (hover:hover){
  .eos-mcard:hover{transform:translateY(var(--eos-lift))}
  .eos-mcard:hover::before,.eos-mcard:hover::after{opacity:1}
  .eos-mcard:hover .eos-tile{transform:translateY(var(--eos-lift-sm))}
  .eos-mcard:hover .eos-tile::after{opacity:1}
  .eos-mcard:hover:active{transform:translateY(var(--eos-lift)) scale(var(--eos-press))}
}
.eos-mcard:active{transform:scale(var(--eos-press));transition-duration:var(--eos-dur-press)}
.eos-mcard-body{display:flex;flex-direction:column;gap:6px;padding:18px 18px 16px}
.eos-mcard-title{margin:0;font-size:19px;line-height:1.3;font-weight:500;letter-spacing:-.012em;color:var(--eos-text)}
.eos-mcard-sub{margin:0;font-size:15.5px;line-height:1.45;color:var(--eos-text-tertiary)}
.eos-meta{display:flex;align-items:center;gap:8px;min-width:0;margin:12px 0 0;font-size:14.5px;line-height:1;color:var(--eos-text-secondary)}
.eos-meta svg{flex:none}
.eos-meta-count{display:inline-flex;align-items:center;gap:7px;font-variant-numeric:tabular-nums}
.eos-meta-sep,.eos-meta-by{color:var(--eos-text-tertiary)}
.eos-meta-maker{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.eos-mcard-link{color:inherit;text-decoration:none;font:inherit;letter-spacing:inherit;background:none;border:0;padding:0;margin:0;cursor:pointer;text-align:inherit}
.eos-mcard-link::after{content:"";position:absolute;inset:0;z-index:3;border-radius:var(--eos-radius-card)}
.eos-mcard-link:focus-visible{outline:none}
.eos-mcard:has(.eos-mcard-link:focus-visible){outline:2px solid var(--eos-focus);outline-offset:3px}
.eos-mcard[data-media=frame]{padding:0;background:transparent;border:0;box-shadow:none;-webkit-backdrop-filter:none;backdrop-filter:none}
.eos-mcard[data-media=frame]::before,.eos-mcard[data-media=frame]::after{display:none}
.eos-mcard[data-media=frame] .eos-mcard-body{display:contents}
.eos-mcard[data-media=frame] .eos-mcard-title{order:-2;margin:0 4px 8px;font-family:var(--eos-font-display);font-weight:var(--eos-display-weight);font-size:var(--eos-mcard-title,32px);line-height:1.08;letter-spacing:var(--eos-display-tracking)}
.eos-mcard[data-media=frame] .eos-mcard-sub{order:-1;margin:0 4px 18px}
.eos-mcard[data-media=frame] .eos-meta{margin:16px 4px 0}
.eos-mcard-frame{position:relative;display:flex;align-items:center;justify-content:center;gap:12px;box-sizing:border-box;border-radius:var(--eos-radius-card);background:var(--eos-well);border:1px solid var(--eos-hairline)}
.eos-mcard-frame::before,.eos-mcard-frame::after{content:"";position:absolute;inset:-1px;border-radius:inherit;opacity:0;pointer-events:none;transition:opacity var(--eos-dur-hover) var(--eos-ease)}
.eos-mcard-frame::before{box-shadow:var(--eos-lift-shadow)}
.eos-mcard-frame::after{border:1px solid var(--eos-hairline-strong)}
@media (hover:hover){.eos-mcard[data-media=frame]:hover .eos-mcard-frame::before,.eos-mcard[data-media=frame]:hover .eos-mcard-frame::after{opacity:1}}
.eos-mcard-band{position:absolute;left:20px;right:20px;top:18px;height:5px;border-radius:999px}
${SR_ONLY_CSS}
`;

/** The installs icon: two stacked rounded squares. */
function InstallsIcon() {
  return (
    <svg width="17" height="17" viewBox="0 0 18 18" aria-hidden>
      <rect x="1.5" y="1.5" width="11" height="11" rx="3" fill="currentColor" opacity=".45" />
      <rect x="5.5" y="5.5" width="11" height="11" rx="3" fill="currentColor" />
    </svg>
  );
}

export interface EosMarketCardProps extends Omit<HTMLAttributes<HTMLElement>, "title"> {
  title?: string;
  subline?: string;
  apps?: readonly EosAppKind[];
  gradient?: EosGradientName;
  tileTone?: EosIconTileTone;
  tileSize?: EosIconTileSize;
  /** How many installs, already formatted (e.g. "12.4k"). */
  installs?: string;
  maker?: string;
  makerMark?: EosMarkKind;
  /** Where the card leads; the whole card becomes the link. */
  href?: string;
  /** Or what opening it does, when there is no address. */
  onOpen?: MouseEventHandler<HTMLButtonElement>;
  /** A gradient banner, or a big title over a pale specimen frame. By default the look decides. */
  media?: "banner" | "frame";
  /** The banner's or frame's height. By default --eos-media-height (196px) or --eos-frame-height (220px), so a page can set it per look. */
  mediaHeight?: number | string;
  flip?: boolean;
  headingLevel?: 2 | 3 | 4;
  style?: CSSProperties;
}

export function EosMarketCard({
  title = "Morning brief",
  subline = "Calendar, inbox and weather in one note at 7:00.",
  apps = ["calendar", "mail", "notes"],
  gradient = "dawn",
  tileTone,
  tileSize = "md",
  installs = "12.4k",
  maker = "Morrow",
  makerMark = "sun",
  href,
  onOpen,
  media,
  mediaHeight,
  flip,
  headingLevel = 3,
  className,
  style,
  ...rest
}: EosMarketCardProps) {
  const layout = EOS_LOOK_SPECS[useEosTheme()?.look ?? "pastel"].layout;
  const shown = media ?? layout.cards;
  const Heading = `h${headingLevel}` as "h3";
  const name = href ? (
    <a className="eos-mcard-link" href={href}>
      {title}
    </a>
  ) : onOpen ? (
    <button type="button" className="eos-mcard-link" onClick={onOpen}>
      {title}
    </button>
  ) : (
    title
  );
  const meta = (
    <p className="eos-meta">
      <span className="eos-meta-count">
        <InstallsIcon />
        {installs}
        <span className="eos-sr"> installs</span>
      </span>
      <span className="eos-meta-sep" aria-hidden>
        ·
      </span>
      <span className="eos-meta-by">by</span>
      <EosMark kind={makerMark} size={18} />
      <span className="eos-meta-maker">{maker}</span>
    </p>
  );

  // One structure for both media, so a change of look keeps the card and its text: only the media swaps, and the
  // frame lifts the title above it with CSS.
  return (
    <EosScope>
      <style>{CSS}</style>
      <article {...rest} className={cx("eos-mcard", className)} data-media={shown} style={style}>
        {shown === "frame" ? (
          <div key="frame" className="eos-mcard-frame" style={{ height: mediaHeight ?? "var(--eos-frame-height, 220px)" }}>
            <span className="eos-mcard-band" style={{ background: `var(--eos-gradient-${gradient})` }} aria-hidden />
            {apps.map((app, i) => (
              <EosIconTile key={`${app}-${i}`} app={app} tone="white" size={tileSize} style={{ "--eos-tile-i": i } as CSSProperties} />
            ))}
          </div>
        ) : (
          <EosGradientBanner
            key="banner"
            gradient={gradient}
            apps={apps}
            tileTone={tileTone ?? layout.tiles}
            tileSize={tileSize}
            height={mediaHeight ?? "var(--eos-media-height, 196px)"}
            flip={flip}
          />
        )}
        <div className="eos-mcard-body">
          <Heading className="eos-mcard-title">{name}</Heading>
          {subline && <p className="eos-mcard-sub">{subline}</p>}
          {meta}
        </div>
      </article>
    </EosScope>
  );
}

// @zeus-internal
/** Small helpers the Eos pieces share. */
import { useCallback, useEffect, useLayoutEffect, useState } from "react";

export const cx = (...parts: (string | false | null | undefined)[]) => parts.filter(Boolean).join(" ");

export const useIsoLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

/** A value that is controlled when `value` is given and owned here otherwise. */
export function useControlled<T>(value: T | undefined, initial: T, onChange?: (next: T) => void) {
  const [own, setOwn] = useState(initial);
  const current = value === undefined ? own : value;
  const set = useCallback(
    (next: T) => {
      if (value === undefined) setOwn(next);
      onChange?.(next);
    },
    [value, onChange],
  );
  return [current, set] as const;
}

/**
 * Whether a media query matches. The server and the first render use `initial`, so markup hydrates; the real answer
 * follows once mounted, and changes as the window does.
 */
export function useMedia(query: string, initial = false): boolean {
  const [matches, setMatches] = useState(initial);
  useEffect(() => {
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const list = window.matchMedia(query);
    const update = () => setMatches(list.matches);
    update();
    list.addEventListener?.("change", update);
    return () => list.removeEventListener?.("change", update);
  }, [query]);
  return matches;
}

/** The index a roving-focus key moves to, or -1 for a key the group ignores. */
export function rovingIndex(key: string, index: number, count: number): number {
  if (count === 0) return -1;
  if (key === "ArrowRight" || key === "ArrowDown") return (index + 1) % count;
  if (key === "ArrowLeft" || key === "ArrowUp") return (index - 1 + count) % count;
  if (key === "Home") return 0;
  if (key === "End") return count - 1;
  return -1;
}

/** Visually hidden text for assistive technology. */
export const SR_ONLY_CSS =
  ".eos-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}";
